package com.loanops.fincompass.opportunity;
import com.loanops.fincompass.matching.MatchService;import com.loanops.fincompass.simulation.*;import com.loanops.fincompass.twin.*;import java.time.Clock;import java.util.*;import static com.loanops.fincompass.opportunity.OpportunityModels.*;
public final class OpportunityService {private final OpportunityStore store;private final OpportunityEngine engine;private final FinancialTwinStore twins;private final ScenarioService scenarios;private final MatchService matches;private final Policy policy;private final Clock clock;public OpportunityService(OpportunityStore store,OpportunityEngine engine,FinancialTwinStore twins,ScenarioService scenarios,MatchService matches,Policy policy,Clock clock){this.store=store;this.engine=engine;this.twins=twins;this.scenarios=scenarios;this.matches=matches;this.policy=policy;this.clock=clock;}
 public List<Event> detect(String owner){var latestHome=scenarios.list(owner).stream().filter(s->"HOME".equals(s.kind())).findFirst().orElse(null);return detect(owner,latestHome==null?null:latestHome.scenarioId(),null);}
 public List<Event> detect(String owner,UUID scenarioId,UUID matchRunId){var current=twins.latest(owner);var home=scenarioId==null?null:scenarios.get(owner,scenarioId);var runs=matchRunId==null?matches.list(owner):List.of(matches.get(owner,matchRunId));for(var draft:engine.evaluate(current,twins.history(owner),home,runs,policy))store.save(owner,draft,policy,clock.instant());return store.active(owner);}public List<Event> active(String owner){return store.active(owner);}public Policy policy(){return policy;}}
